/// `README.md`, line 25.
#[rustfmt::skip]
#[test]
fn readme_snippet_1() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clifacet::contract::ExitPolicy;
    use clifacet::policy::{Capabilities, Mode, Policy};
    use clifacet::{Facet, Failure};
    /// An application controller declares its global surface, context, and commands.
    #[clifacet::app(name = "greet", about = "Say hello", commands)]
    struct GreetApp {}
    #[clifacet::commands]
    impl GreetApp {
        /// The greeting command: parameters are arguments and flags.
        pub fn hello(
            &self,
            #[clifacet(long, short = 'n', help = "Who to greet", default_value = "world")]
            name: String,
            #[clifacet(long, help = "How many times", default_value_t = 1)]
            repeat: u8,
        ) -> Result<String, Failure> {
            Ok(format!("hello, {name} x{repeat}"))
        }
    }
    /// An application is a value built from parts that each own one decision.
    fn app() -> clifacet::App<'static, GreetApp> {
        clifacet::App::<GreetApp>::for_cli()
            .policy(Policy::up_to(Mode::Interactive))
            .exit(ExitPolicy::standard())
    }
    /// `main` is the same value, run.
    fn main_line() -> std::process::ExitCode {
        clifacet::run_cli::<GreetApp>()
    }
    /// And a test is the same value with the process taken out of it.
    fn scripted() -> i32 {
        let mut out = Vec::new();
        let mut err = Vec::new();
        app().run_with(
            ["greet", "hello", "--name", "ada"],
            Capabilities::headless(),
            || Box::new(clifacet::prompt::Terminal::new(std::io::empty(), std::io::sink())),
            &mut out,
            &mut err,
        )
    }
    assert_eq!(scripted(), 0);
}

/// `modes.mdx`, line 13.
#[rustfmt::skip]
#[test]
fn modes_snippet_1() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clifacet::policy::{Capabilities, Mode, Policy, Request};
    let plan = Policy::up_to(Mode::Interactive)
        .resolve(Request::mode(Mode::Interactive), Capabilities::terminal())
        .expect("a terminal can host prompts");
    assert_eq!(plan.mode(), Mode::Interactive);
    // A request the application does not allow is refused, not silently downgraded.
    let refused = Policy::up_to(Mode::Interactive)
        .resolve(Request::mode(Mode::Tui), Capabilities::terminal_with_tui());
    assert!(refused.is_err());
}

/// `modes.mdx`, line 36.
#[rustfmt::skip]
#[test]
fn modes_snippet_2() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clifacet::policy::{Capabilities, Mode, Policy, Request};
    let policy = Policy::up_to(Mode::Tui).prefer(Mode::Interactive);
    let plan = policy
        .resolve(Request::none(), Capabilities::terminal_with_tui())
        .expect("prompts are permitted and possible");
    assert_eq!(plan.mode(), Mode::Interactive, "the preference, not the ceiling");
    let plan = policy
        .resolve(Request::mode(Mode::Tui), Capabilities::terminal_with_tui())
        .expect("a TUI is permitted here");
    assert_eq!(plan.mode(), Mode::Tui);
    let cautious = Policy::up_to(Mode::Tui).prefer(Mode::NonInteractive);
    let plan = cautious
        .resolve(Request::none(), Capabilities::terminal())
        .expect("a run that asks nothing always resolves");
    assert_eq!(plan.mode(), Mode::NonInteractive);
}

